# Let's first do a keyword-based pre-filter to identify potential booking issue dialogs
import re

booking_keywords = ['book', 'booking', 'reservation', 'cancel', 'cancellation', 'reschedule', 
                    'rebook', 'confirm', 'confirmation', 'itinerary', 'flight change',
                    'modify', 'modification', 'refund', 'ticket', 'booked']

def has_booking_keywords(dialog_text):
    text_lower = dialog_text.lower()
    return any(kw in text_lower for kw in booking_keywords)

# Count potential booking-related dialogs per company
